import copy
import re
from ta_emss.utilities.structure_to_lowercase import convert_structure_to_lowercase


class FSM_Configurator(object):
    def __init__(self, ta_emss, send=True, activate=False):
        super(FSM_Configurator, self).__init__()
        self.configuration = {}
        self.moi_to_dn = {}
        self.deconfiguration = {}
        self._temporary_configuration = {}
        self._ta_emss = ta_emss
        self._send = send
        self._activate = activate
        self._object_details = {}
        self._reset_required = False

    def parse_configuration(self, configuration):
        config = {}
        self.moi_to_dn = configuration.pop('DN', {})
        for object_name, attributes in configuration.items():
            config[object_name.upper()] = convert_structure_to_lowercase(attributes, keys_only=True)
        return config

    def configure(self, requested_configuration):
        self.configuration = self.parse_configuration(requested_configuration)
        self._is_plan_empty = True
        self.apply_configuration(self.configuration)
        self.deconfiguration = self._temporary_configuration
        self._temporary_configuration = {}
        if not self._is_plan_empty and self._send:
            self._ta_emss.apply_planned_changes(activate=self._activate)
        return True

    def deconfigure(self):
        self._is_plan_empty = True
        self.apply_configuration(self.deconfiguration)
        self._temporary_configuration = {}
        if not self._is_plan_empty and self._send:
            self._ta_emss.apply_planned_changes(activate=self._activate)

    def is_object_exists(self, object):
        return self._ta_emss.check_if_object_exists(object, silent=True)

    def is_attribute_exists(self, object, attribute):
        return self._ta_emss.check_if_attribute_exists(object, attribute, silent=True)

    def is_object_to_delete(self, object_configuration):
        if object_configuration is None or object_configuration == "":
            return True
        else:
            return False

    def is_attribute_to_delete(self, attribute_value):
        return attribute_value == ""

    def is_structural_attribute(self, attribute_value):
        return isinstance(attribute_value, list)

    def apply_configuration(self, configuration_to_apply):
        self._ta_emss.create_new_plan()
        for object, object_configuration in configuration_to_apply.items():
            self._object_details[object] = self._ta_emss.get_object_attributes_details(object, silent=True)
            if not self.is_object_exists(object):
                self._temporary_configuration[object] = ""
                self.configure_new_object(object, object_configuration)
            else:
                self._temporary_configuration[object] = {}
                self.reconfigure_existing_object(object, object_configuration)
        if self._is_plan_empty:
            self._ta_emss.destroy_existing_plan()

    def is_record_with_subattributes(self, record):
        return isinstance(record, dict)

    def configure_new_object(self, object, object_configuration):
        if not self.is_object_to_delete(object_configuration):
            self.add_object_creation_to_plan(object)
            self.configure_attributes_of_new_object(object, object_configuration)
            self._is_plan_empty = False

    def add_object_creation_to_plan(self, object):
        if object in self.moi_to_dn:
            object = self.moi_to_dn[object]
        self._ta_emss.plan_object_creation(object, only_mandatory=True)
        self._temporary_configuration[object] = ""

    def configure_attributes_of_new_object(self, object, object_configuration):
        for attribute, attribute_value in object_configuration.items():
            if self.is_structural_attribute(attribute_value):
                self.configure_structural_attribute_of_new_object(object, attribute, attribute_value)
            else:
                self.configure_scalar_attribute_of_new_object(object, attribute, attribute_value)

    def configure_structural_attribute_of_new_object(self, object, attribute, attribute_value):
        self.add_proper_value_of_records_to_plan(object, attribute, attribute_value)
        self.configure_records_of_structural_attribute(object, attribute, attribute_value)

    def configure_records_of_structural_attribute(self, object, attribute, attribute_value):
        for index, record in enumerate(attribute_value):
            if self.is_record_with_subattributes(record):
                self.edit_dict_attribute(object, attribute, index, record)
            else:
                self.edit_list_attribute(object, attribute, index, record)

    def edit_dict_attribute(self, object, attribute, index, value):
        for subattribute, subattribute_value in value.items():
            self._ta_emss.edit_planned_object_attributes(object,
                                                         {"%s.%s[%s]" % (attribute, subattribute, index): self._parse_value_to_edit(subattribute_value)})
            self._check_if_restart_req(object, attribute)

    def edit_list_attribute(self, object, attribute, index, value):
        self._ta_emss.edit_planned_object_attributes(object, {"%s[%s]" % (attribute, index): "[%s]" % self._parse_value_to_edit_list(value)})
        self._check_if_restart_req(object, attribute)

    def add_proper_value_of_records_to_plan(self, object, attribute, attribute_value):
        is_mandatory = self._is_attribute_mandatory(object, attribute)
        number_of_records_to_add = (len(attribute_value) - 1) if is_mandatory else len(attribute_value)
        self.add_records_of_structural_attribute_to_plan(object, attribute, number_of_records_to_add)

    def add_records_of_structural_attribute_to_plan(self, object, attribute, number_of_records_to_add):
        for record_to_add in range(number_of_records_to_add):
            self.add_attribute_to_plan(object, attribute)

    def add_attribute_to_plan(self, object, attribute):
        self._ta_emss.plan_attribute_creation(object, attribute, only_mandatory=True)
        self._check_if_restart_req(object, attribute)

    def configure_scalar_attribute_of_new_object(self, object, attribute, attribute_value):
        if not self._is_attribute_mandatory(object, attribute):
            self.add_attribute_to_plan(object, attribute)
        self.edit_scalar_attribute(object, attribute, attribute_value)

    def edit_scalar_attribute(self, object, attribute, attribute_value):
        self._ta_emss.edit_planned_object_attributes(object, {attribute: self._parse_value_to_edit(attribute_value)})
        self._check_if_restart_req(object, attribute)

    def _parse_value_to_edit_list(self, value):
        val = self._parse_value_to_edit(value)
        srch = re.search(r'^"(.*)"$', val)
        if srch:
            return "'" + srch.group(1) + "'"
        return val

    def _parse_value_to_edit(self, value):
        if ' ' in value:
            while True:
                mod = False
                srch = re.search(r'^"(.*)"$', value)
                if srch:
                    value = srch.group(1)
                    mod = True
                srch = re.search(r"^'(.*)'$", value)
                if srch:
                    value = srch.group(1)
                    mod = True
                if not mod:
                    break
            retval = '"' + value + '"'
            return retval

        if value == '':
            value = '""'
        return value

    def _verify_attribute_defined(self, check, object, attribute):
        if attribute not in self._object_details[object]:
            raise Exception('ERROR during verification of {}: Missing definition of {} in {}. '
                            'Make sure you have the latest PDDB installed or contact EMSsim support at {}'
                            '.'.format(check, attribute, object, self._ta_emss.emss_support))

    def _is_attribute_mandatory(self, object, attribute):
        self._verify_attribute_defined('REQ', object, attribute)
        return self._object_details[object][attribute]['REQ'] == 'M'

    def _is_attribute_modifiable(self, object, attribute):
        self._verify_attribute_defined('MOD', object, attribute)
        return self._object_details[object][attribute]['MOD'] == 'Y'

    def _is_attr_need_to_restart_bts(self, object, attribute):
        self._verify_attribute_defined('CHG', object, attribute)
        if 'CHG' in self._object_details[object][attribute]:
            return self._object_details[object][attribute]['CHG'] in ['UR', 'CR']
        return False

    def _check_if_restart_req(self, object, attribute):
        if self._is_attr_need_to_restart_bts(object, attribute):
            self._reset_required = True

    def reconfigure_existing_object(self, object, object_configuration):
        if self.is_object_to_delete(object_configuration):
            self.add_object_deletion_to_plan(object)
            self.save_current_object_configuration(object)
            self._is_plan_empty = False
        else:
            self.configure_attributes_of_existing_object(object, object_configuration)

    def save_current_object_configuration(self, object):
        attributes = self.get_set_of_all_configured_attributes_of_object(object)
        for attribute in attributes:
            if self._is_attribute_modifiable(object, attribute):
                current_value = self._ta_emss.get_values_of_structural_attribute(object, attribute)
                self.save_current_attribute_configuration(object, attribute, current_value)

    def save_current_attribute_configuration(self, object, attribute, current_value):
        self._temporary_configuration[object][attribute] = current_value

    def get_set_of_all_configured_attributes_of_object(self, object):
        return {attribute.lower().split("[")[0].split(".")[0]
                for attribute in self._ta_emss.get_object_attributes(object, without_set_by_system=True, silent=True)}

    def add_object_deletion_to_plan(self, object):
        self._ta_emss.plan_object_deletion(object)

    def configure_attributes_of_existing_object(self, object, object_configuration):
        for attribute, attribute_value in object_configuration.items():
            if not self.is_current_attribute_value_equal_to_requested(object, attribute, attribute_value):
                self._is_plan_empty = False
                if self.is_attribute_to_delete(attribute_value):
                    self.delete_attribute(object, attribute)
                else:
                    if self.is_structural_attribute(attribute_value):
                        self.configure_structural_attribute_of_existing_object(object, attribute, attribute_value)
                    else:
                        self.configure_scalar_attribute_of_existing_object(object, attribute, attribute_value)

    def is_current_attribute_value_equal_to_requested(self, object, attribute, requested_value):
        try:
            current_value = self._ta_emss.get_values_of_structural_attribute(object, attribute, lower_values=False, can_fail=True, silent=True)
        except Exception:
            current_value = ""
        if self.has_subattributes(current_value):
            for index, record in enumerate(copy.deepcopy(current_value)):
                for subattribute in record:
                    is_mod = self._is_attribute_modifiable(object, attribute + '.' + subattribute)
                    if not is_mod:
                        del current_value[index][subattribute]

        self.save_current_attribute_configuration(object, attribute, current_value)
        return current_value == requested_value

    def has_subattributes(self, value):
        return self.is_structural_attribute(value) and all(self.is_record_with_subattributes(record) for record in value)

    def configure_scalar_attribute_of_existing_object(self, object, attribute, attribute_value):
        self.add_attribute_to_plan(object, attribute)
        self.edit_scalar_attribute(object, attribute, attribute_value)

    def configure_structural_attribute_of_existing_object(self, object, attribute, attribute_value):
        self.configure_proper_number_of_indexes(object, attribute, attribute_value)
        self.configure_records_of_structural_attribute(object, attribute, attribute_value)

    def delete_attribute(self, object, attribute):
        self._ta_emss.plan_attribute_deletion(object, attribute)
        self._check_if_restart_req(object, attribute)

    def configure_proper_number_of_indexes(self, object, attribute, attribute_value):
        required_number_of_indexes = len(attribute_value)
        try:
            current_number_of_indexes = len(self._ta_emss.get_values_of_structural_attribute(object, attribute, can_fail=True, silent=True))
        except Exception:
            current_number_of_indexes = 0
        if required_number_of_indexes > current_number_of_indexes:
            self.add_records_of_structural_attribute_to_plan(object, attribute, required_number_of_indexes - current_number_of_indexes)
        elif required_number_of_indexes < current_number_of_indexes:
            self.delete_records_of_structural_attribute_from_to(object, attribute, required_number_of_indexes - 1, current_number_of_indexes - 1)

    def delete_records_of_structural_attribute_from_to(self, object, attribute, from_index, to_index):
        for index_of_record in sorted(range(from_index, to_index), reverse=True):
            self.delete_record_of_attribute(object, attribute, index_of_record)

    def delete_record_of_attribute(self, object, attribute, index_of_record):
        self._ta_emss.plan_attribute_deletion(object, "%s[%s]" % (attribute, index_of_record))
        self._check_if_restart_req(object, attribute)

    def is_reset_required(self):
        return self._reset_required
